import { useEffect, useMemo, useState } from "react";
import { api } from "./api";
import { ProposalWorkspaceStageAware } from "./ProposalWorkspaceStageAware";

type Role = "SYSTEM_ADMIN" | "OWNER_SPONSOR" | "COMMERCIAL_APPROVER" | "RESPONSIBLE_ENGINEER";
type SourceType = "TENDER_DOCUMENT" | "TENDER_EMAIL" | "TENDER_PHOTO" | "CLIENT_DATA";
const sourceTypes: Array<{ key: SourceType; label: string }> = [
  { key: "TENDER_EMAIL", label: "Tender Email" },
  { key: "TENDER_DOCUMENT", label: "Tender Document" },
  { key: "TENDER_PHOTO", label: "Tender Photo / Image" },
  { key: "CLIENT_DATA", label: "Client Information" },
];
const lifecycleLabels = ["Intake & Sources", "Engineering Preparation", "Commercial Review", "Client Response", "Contract Handoff"];
const sourceDisplay: Record<string, string> = { TENDER_EMAIL: "Tender Email", TENDER_DOCUMENT: "Tender Document", TENDER_PHOTO: "Tender Photo / Image", CLIENT_DATA: "Client Information" };
const roleLabel: Record<Role, string> = { SYSTEM_ADMIN: "Owner", OWNER_SPONSOR: "Owner", COMMERCIAL_APPROVER: "Business Development", RESPONSIBLE_ENGINEER: "Engineering" };
const REGISTER_OWNER_ERROR = "We couldn't load the Proposal Register. Please retry.";
function headers(role: Role) { return { "X-Dev-Role": role }; }

const asList = (value: unknown): any[] => Array.isArray(value) ? value : [];
const asRecord = (value: unknown): Record<string, any> => value && typeof value === "object" && !Array.isArray(value) ? value as Record<string, any> : {};
function validateProposalRegister(data: unknown): asserts data is { items: any[]; lane_counts: Record<string, unknown> } {
  if (!data || typeof data !== "object" || Array.isArray(data)) throw new Error("PROPOSAL_REGISTER_CONTRACT_INVALID: response expected object");
  const payload = data as Record<string, unknown>;
  if (!Array.isArray(payload.items)) throw new Error("PROPOSAL_REGISTER_CONTRACT_INVALID: response.items expected array");
  if (!payload.lane_counts || typeof payload.lane_counts !== "object" || Array.isArray(payload.lane_counts)) throw new Error("PROPOSAL_REGISTER_CONTRACT_INVALID: response.lane_counts expected object");
  for (const [key, value] of Object.entries(payload.lane_counts as Record<string, unknown>)) if (typeof value !== "number" || !Number.isInteger(value) || value < 0) throw new Error(`PROPOSAL_REGISTER_CONTRACT_INVALID: response.lane_counts.${key} expected non-negative integer`);
  for (const [index, item] of payload.items.entries()) {
    if (!item || typeof item !== "object" || Array.isArray(item)) throw new Error(`PROPOSAL_REGISTER_CONTRACT_INVALID: response.items[${index}] expected object`);
    const row = item as Record<string, unknown>;
    for (const field of ["id", "proposal", "client", "activity", "stage", "stage_code", "current_owner"]) if (typeof row[field] !== "string") throw new Error(`PROPOSAL_REGISTER_CONTRACT_INVALID: response.items[${index}].${field} expected string`);
    if (row.last_activity !== null && typeof row.last_activity !== "string") throw new Error(`PROPOSAL_REGISTER_CONTRACT_INVALID: response.items[${index}].last_activity expected ISO string or null`);
    if (!row.next_action || typeof row.next_action !== "object" || Array.isArray(row.next_action)) throw new Error(`PROPOSAL_REGISTER_CONTRACT_INVALID: response.items[${index}].next_action expected object`);
    if (!row.owner_lane || typeof row.owner_lane !== "object" || Array.isArray(row.owner_lane)) throw new Error(`PROPOSAL_REGISTER_CONTRACT_INVALID: response.items[${index}].owner_lane expected object`);
    if (typeof row.contract_eligible !== "boolean") throw new Error(`PROPOSAL_REGISTER_CONTRACT_INVALID: response.items[${index}].contract_eligible expected boolean`);
    if (!row.validation || typeof row.validation !== "object" || Array.isArray(row.validation)) throw new Error(`PROPOSAL_REGISTER_CONTRACT_INVALID: response.items[${index}].validation expected object`);
  }
}
function normalizeProposal(raw: any) {
  if (!raw || typeof raw !== "object" || !raw.id || !raw.title || !raw.stage) throw new Error("PROPOSAL_DETAIL_CONTRACT_INVALID");
  const forms = asRecord(raw.forms_v2);
  const hardening = asRecord(raw.hardening);
  return {
    ...raw,
    fields: asRecord(raw.fields), lifecycle: asList(raw.lifecycle), sources: asList(raw.sources), notes: asList(raw.notes), site_photos: asList(raw.site_photos), revision_history: asList(raw.revision_history),
    forms_v2: { ...forms, stakeholders: asList(forms.stakeholders), source_links: asList(forms.source_links), source_conflicts: asList(forms.source_conflicts), service_scope_items: asList(forms.service_scope_items), regulatory_scope_intents: asList(forms.regulatory_scope_intents), assumptions: asList(forms.assumptions), external_cost_assumptions: asList(forms.external_cost_assumptions), engineering_contributions: asList(forms.engineering_contributions), proposal_form: asList(forms.proposal_form) },
    hardening: { ...hardening, stakeholders: asList(hardening.stakeholders), unknowns: asList(hardening.unknowns), conflicts: asList(hardening.conflicts), material_acknowledgments: asList(hardening.material_acknowledgments), active_staleness: asList(hardening.active_staleness), client_responses: asList(hardening.client_responses), revisions: asList(hardening.revisions), material_open_unknowns: asList(hardening.material_open_unknowns), material_open_conflicts: asList(hardening.material_open_conflicts) },
    validation: { blockers: [], warnings: [], ...(asRecord(raw.validation)) }, intake_readiness: { ready: false, blockers: [], warnings: [], ...(asRecord(raw.intake_readiness)) }, outputs: { available: false, ...(asRecord(raw.outputs)) }, configuration: asRecord(raw.configuration), proposal_breakdown: { items: [], commercial_summary: {}, ...(asRecord(raw.proposal_breakdown)) }, authority: asRecord(raw.authority),
  };
}
function registerError(cause: unknown): string {
  const technical = cause instanceof Error ? cause.message : String(cause || "Proposal register unavailable.");
  console.info("Proposal Register load diagnostic", { code: technical.startsWith("PROPOSAL_REGISTER_CONTRACT_INVALID") ? "PROPOSAL_REGISTER_CONTRACT_INVALID" : "PROPOSAL_REGISTER_LOAD_FAILED", technical_message: technical, endpoint: "/api/bd/proposals" });
  return REGISTER_OWNER_ERROR;
}

export function BDProposalOwnerSessionPage({ role }: { role: Role }) {
  const routeSegment = window.location.pathname.startsWith("/opportunities/") ? window.location.pathname.split("/")[2] || null : null;
  const routeId = routeSegment && routeSegment !== "new" ? routeSegment : null;
  const [selected, setSelected] = useState<string | null>(routeId);
  const [newProposal, setNewProposal] = useState(routeSegment === "new");
  const [showSettings, setShowSettings] = useState(false);
  useEffect(() => { const onPopState = () => { const nextSegment = window.location.pathname.startsWith("/opportunities/") ? window.location.pathname.split("/")[2] || null : null; setSelected(nextSegment && nextSegment !== "new" ? nextSegment : null); setNewProposal(nextSegment === "new"); }; window.addEventListener("popstate", onPopState); return () => window.removeEventListener("popstate", onPopState); }, []);
  const openProposal = (id: string) => { window.history.pushState({}, "", `/opportunities/${id}`); setSelected(id); setNewProposal(false); };
  const openNew = () => { window.history.pushState({}, "", "/opportunities/new"); setNewProposal(true); setSelected(null); };
  const backToList = () => { window.history.pushState({}, "", "/opportunities"); setSelected(null); setNewProposal(false); };
  return <div className="workflow-page bd-session">
    {!selected && !newProposal && !showSettings ? <ProposalList role={role} onOpen={openProposal} onNew={openNew} onSettings={() => setShowSettings(true)} /> : showSettings ? <ProposalInputs role={role} onBack={() => setShowSettings(false)} /> : <ProposalWorkbench role={role} proposalId={selected} onBack={backToList} onCreated={openProposal} />}
  </div>;
}

function ProposalList({ role, onOpen, onNew, onSettings }: { role: Role; onOpen: (id: string) => void; onNew: () => void; onSettings: () => void }) {
  const [rows, setRows] = useState<any[]>([]); const [q, setQ] = useState(""); const [client, setClient] = useState(""); const [activity, setActivity] = useState(""); const [location, setLocation] = useState(""); const [stage, setStage] = useState(""); const [lane, setLane] = useState("ALL"); const [laneCounts, setLaneCounts] = useState<Record<string, number>>({}); const [error, setError] = useState(""); const [loading, setLoading] = useState(true);
  const load = () => { setError(""); if (!rows.length && !Object.keys(laneCounts).length) setLoading(true); const params = new URLSearchParams({ q, lane, ...(client ? { client } : {}), ...(activity ? { activity } : {}), ...(location ? { location } : {}), ...(stage ? { stage } : {}) }); return api<any>(`/api/bd/proposals?${params.toString()}`, { headers: headers(role) }).then((data) => { validateProposalRegister(data); setRows(data.items); setLaneCounts(data.lane_counts as Record<string, number>); }).catch((cause) => { setRows([]); setLaneCounts({}); setError(registerError(cause)); }).finally(() => setLoading(false)); };
  useEffect(() => { void load(); }, [role, q, client, activity, location, stage, lane]);
  const laneLabels = [{ code: "ALL", label: "All" }, { code: "NEED_ACTION", label: "Need Action" }, { code: "AUTHORITY_REVIEW", label: "Authority Review" }, { code: "READY_CLOSE", label: "Ready / Close" }];
  return <>
    <div className="page-intro"><div><span className="eyebrow">BD · PROPOSALS</span><h2>Proposal Register</h2><p>One Proposal identity from client inputs through Engineering, commercial review, and Contract Handoff.</p></div><div><span className="tag">{roleLabel[role]}</span><button className="text-button" onClick={onSettings}>Inputs &amp; Go-Live</button></div></div>
    {error && <div className="error-state" role="alert">{error}<button className="text-button" onClick={() => void load()}>Retry</button></div>}
    <section className="panel bd-list-panel"><div className="bd-lane-tabs" role="tablist" aria-label="Proposal work lanes">{laneLabels.map((item) => <button key={item.code} type="button" role="tab" aria-selected={lane === item.code} className={`bd-lane-tab ${lane === item.code ? "active" : ""}`} onClick={() => setLane(item.code)}>{item.label}<strong>{loading ? "…" : error ? "—" : laneCounts[item.code] ?? "—"}</strong></button>)}</div><div className="proposals-toolbar"><div className="filter-row bd-search-fields"><label>Client<input aria-label="Search proposals by client" placeholder="Client name / company" value={client} onChange={(event) => setClient(event.target.value)} /></label><label>Activity<input aria-label="Search proposals by activity" placeholder="Activity or project description" value={activity} onChange={(event) => setActivity(event.target.value)} /></label><label>Location<input aria-label="Search proposals by location" placeholder="Site / property location" value={location} onChange={(event) => setLocation(event.target.value)} /></label><label className="bd-search-wide">Reference / all<input aria-label="Search proposals by reference" placeholder="Proposal, project ref, scope…" value={q} onChange={(event) => setQ(event.target.value)} /></label><label>Stage<select aria-label="Filter stage" value={stage} onChange={(event) => setStage(event.target.value)}><option value="">All stages</option><option value="RECEIVED">Received</option><option value="IN_REVIEW">Intake &amp; Sources</option><option value="PROPOSAL_PREPARATION">Engineering Preparation</option><option value="PROPOSAL_HANDOVER">Commercial Review</option><option value="READY_FOR_QUOTATION">Ready for Quotation</option><option value="COMMERCIAL_REVIEW">Commercial Review</option><option value="QUOTATION_IN_PROGRESS">Quotation in Progress</option><option value="CLIENT_RESPONSE_PENDING">Client Response</option><option value="ACCEPTED">Accepted</option><option value="CONTRACT_HANDOVER">Contract Handoff</option><option value="CLOSED">Closed</option></select></label></div>{role !== "RESPONSIBLE_ENGINEER" && <button className="button-primary" onClick={onNew}>＋ New Proposal</button>}</div>
      <div className="table-panel"><table><thead><tr><th>Proposal Description</th><th>Project Ref</th><th>Client</th><th>Stage</th><th>Amount</th><th>Next Action</th><th>Last Activity</th><th>Open</th></tr></thead><tbody>{loading && <tr><td colSpan={8}><div className="empty-state"><b>Loading Proposals…</b></div></td></tr>}{!loading && !error && rows.map((row) => <tr key={row.id}><td><b>{row.proposal}</b><small className="proposal-row-sub">{row.proposal_reference}</small></td><td>{row.project_ref || "Provisional"}</td><td>{row.client}</td><td><span className="status status-under-review">{row.stage}</span></td><td>{row.amount || "Not set"}</td><td>{row.next_action?.label || "Review Proposal"}</td><td>{row.last_activity ? new Date(row.last_activity).toLocaleString([], { dateStyle: "medium", timeStyle: "short" }) : "Not recorded"}</td><td><button className="text-button" onClick={() => onOpen(row.id)}>Open →</button></td></tr>)}{!loading && !error && !rows.length && <tr><td colSpan={8}><div className="empty-state"><b>No Proposal records match the current filter.</b><p>Try another lane, Client, Activity, Location, or reference.</p></div></td></tr>}</tbody></table></div></section>
    <div className="proposal-sor-note"><span className="proposal-blue-dot" /><span>Lane counts and rows come from the same backend predicates. Dashboard remains canonical for Proposal Template, Checklist, Definitions, and Engineering Works.</span></div>
  </>;
}

function ProposalInputs({ role, onBack }: { role: Role; onBack: () => void }) {
  const [items, setItems] = useState<any[]>([]); const [error, setError] = useState(""); const [saved, setSaved] = useState(false);
  useEffect(() => { api<any>("/api/bd/proposals/settings/go-live", { headers: headers(role) }).then((data) => setItems(data.items || [])).catch((cause) => setError(cause instanceof Error ? cause.message : "Inputs could not be loaded.")); }, [role]);
  const update = (key: string, raw: string) => setItems((current) => current.map((item) => item.key === key ? { ...item, value: { ...item.value, value: raw } } : item));
  const save = async () => { try { await api("/api/bd/proposals/settings/go-live", { method: "PUT", headers: { ...headers(role), "Content-Type": "application/json" }, body: JSON.stringify({ settings: Object.fromEntries(items.map((item) => [item.key, item.value])) }) }); setSaved(true); } catch (cause) { setError(cause instanceof Error ? cause.message : "Inputs could not be saved."); } };
  return <section className="panel route-detail-page"><div className="panel-head"><div><span className="eyebrow">BD · INPUTS &amp; GO-LIVE</span><h2>Operating decisions</h2><p>Safe defaults are explicit and remain pending until an Owner confirms them.</p></div><button className="text-button" onClick={onBack}>← Proposal list</button></div>{error && <div className="error-state" role="alert">{error}</div>}{saved && <div className="inline-message" role="status">Owner decisions persisted.</div>}<div className="bd-form-grid">{items.map((item) => <label key={item.key}>{item.key.replaceAll("_", " ")}<textarea value={item.value?.value || ""} onChange={(event) => update(item.key, event.target.value)} disabled={role === "RESPONSIBLE_ENGINEER"} /><small>{item.status} · {item.notes}</small></label>)}</div>{role !== "RESPONSIBLE_ENGINEER" && <button className="button-primary" onClick={() => void save()}>Save Owner decisions</button>}</section>;
}

function ProposalWorkbench({ role, proposalId, onBack, onCreated }: { role: Role; proposalId: string | null; onBack: () => void; onCreated: (id: string) => void }) {
  const [proposal, setProposal] = useState<any>(null); const creating = !proposalId; const [busy, setBusy] = useState(false); const [message, setMessage] = useState(""); const [error, setError] = useState(""); const [loading, setLoading] = useState(Boolean(proposalId)); const [createSource, setCreateSource] = useState<SourceType | null>(null); const [sourceFile, setSourceFile] = useState<File | null>(null);
  const [createForm, setCreateForm] = useState({ proposal_description: "", project_reference: "", client_name: "", source_title: "", source_date: "", source_notes: "" });
  const load = () => { if (!proposalId) return Promise.resolve(); setLoading(true); setError(""); return api<any>(`/api/bd/proposals/${proposalId}`, { headers: headers(role) }).then((data) => setProposal(normalizeProposal(data))).catch((cause) => { setProposal(null); setError(cause instanceof Error ? cause.message : "Proposal workspace unavailable." ); }).finally(() => setLoading(false)); };
  useEffect(() => { void load(); }, [proposalId, role]);
  const create = async () => { setError(""); if (!createForm.proposal_description.trim() || !createForm.client_name.trim()) { setError("Proposal Description and Client are required to create the draft."); return; } if (createSource && !sourceFile) { setError(`Select a source file for ${sourceDisplay[createSource]} before creating the Proposal.`); return; } setBusy(true); try { let result: any; if (createSource && sourceFile) { const form = new FormData(); form.append("proposal_description", createForm.proposal_description.trim()); form.append("project_reference", createForm.project_reference); form.append("client_name", createForm.client_name.trim()); form.append("initial_source_type", createSource); form.append("source_title", createForm.source_title); form.append("source_date", createForm.source_date); form.append("source_notes", createForm.source_notes); form.append("file", sourceFile); result = await api<any>("/api/bd/proposals/intake", { method: "POST", headers: headers(role), body: form }); } else { result = await api<any>("/api/bd/proposals", { method: "POST", headers: { ...headers(role), "Content-Type": "application/json" }, body: JSON.stringify({ proposal_description: createForm.proposal_description, project_reference: createForm.project_reference, client_name: createForm.client_name }) }); } onCreated(result.proposal?.id || result.id); } catch (cause) { setError(cause instanceof Error ? cause.message : "Proposal draft could not be created. No source was claimed."); } finally { setBusy(false); } };
  if (creating) return <section className="panel route-detail-page bd-create-panel"><div className="panel-head"><div><span className="eyebrow">BD · NEW PROPOSAL</span><h2>New Proposal Intake</h2><p>Create one Proposal context, then add one or more Tender &amp; Client Sources. Client List, Proposal Form, and Contract Form remain in their own contexts.</p></div><button className="text-button" onClick={onBack}>← Proposal list</button></div>{error && <div className="error-state" role="alert">{error}</div>}<div className="bd-form-grid"><label>Proposal Description<input aria-label="Proposal Description" value={createForm.proposal_description} onChange={(event) => setCreateForm({ ...createForm, proposal_description: event.target.value })} /></label><label>Commercial Client<input aria-label="Client" value={createForm.client_name} onChange={(event) => setCreateForm({ ...createForm, client_name: event.target.value })} /></label><label>Opportunity Ref (provisional)<input aria-label="Project Ref" value={createForm.project_reference} onChange={(event) => setCreateForm({ ...createForm, project_reference: event.target.value })} /></label></div><div className="proposal-intake-step"><h3>Start with a source (optional)</h3><p className="muted">Select one source family to prepare its bounded intake before the Proposal exists. The source is persisted only after the Proposal draft is created successfully.</p><div className="bd-source-grid">{sourceTypes.map((item) => <button type="button" key={item.key} aria-pressed={createSource === item.key} className={`bd-source-card ${createSource === item.key ? "complete" : ""}`} onClick={() => setCreateSource(item.key)}><b>{item.label}</b><small>{createSource === item.key ? "Selected · intake panel open" : "Choose to prepare this source"}</small></button>)}</div>{createSource && <div className="bd-source-intake-panel" aria-live="polite"><h4>{sourceDisplay[createSource]} intake</h4><p className="muted">This source remains evidence with provenance. Extraction does not overwrite Proposal values.</p><div className="bd-form-grid"><label>Source title / description<input aria-label="Initial source title" value={createForm.source_title} onChange={(event) => setCreateForm({ ...createForm, source_title: event.target.value })} placeholder={sourceDisplay[createSource]} /></label><label>Source date<input aria-label="Initial source date" type="date" value={createForm.source_date} onChange={(event) => setCreateForm({ ...createForm, source_date: event.target.value })} /></label><label className="wide">Notes<textarea aria-label="Initial source notes" value={createForm.source_notes} onChange={(event) => setCreateForm({ ...createForm, source_notes: event.target.value })} placeholder="Human-entered source context" /></label><label className="wide">{createSource === "CLIENT_DATA" ? "Client information file / supporting document" : `${sourceDisplay[createSource]} file`}<input aria-label={`${sourceDisplay[createSource]} source file`} type="file" onChange={(event) => setSourceFile(event.target.files?.[0] || null)} /></label></div>{sourceFile && <p className="inline-message" role="status">Selected source: {sourceFile.name}</p>}</div>}</div><button className="button-primary" onClick={() => void create()} disabled={busy}>{busy ? "Creating…" : createSource ? `Create Proposal & Add ${sourceDisplay[createSource]}` : "Create Proposal Intake"}</button></section>;
  if (loading) return <section className="panel"><b>Loading Proposal workspace…</b></section>;
  if (error && !proposal) return <section className="panel error-state" role="alert"><b>Could not load this Proposal.</b><p>{error.includes("PROPOSAL_NOT_FOUND") ? "The Proposal no longer exists or is not available to this user." : "The Proposal workspace is temporarily unavailable."}</p><button className="text-button" onClick={() => void load()}>Retry</button><button className="text-button" onClick={onBack}>← Proposal list</button></section>;
  return <ProposalWorkspaceStageAware role={role} proposal={proposal} setProposal={setProposal} onBack={onBack} setMessage={setMessage} message={message} error={error} setError={setError} load={load} />;
}

function ProposalWorkspaceDetail({ role, proposal, setProposal, onBack, setMessage, message, error, setError }: any) {
  const readOnly = role === "RESPONSIBLE_ENGINEER"; const technicalKeys = new Set(["scope_of_work", "sow", "process_of_work", "technical_assumptions", "technical_deliverables"]); const [fields, setFields] = useState({ ...(proposal.fields || {}) }); const [amec, setAmec] = useState(JSON.stringify(proposal.amec_input || {}, null, 2)); const [saving, setSaving] = useState(false); const [sourceBusy, setSourceBusy] = useState<string | null>(null); const [noteType, setNoteType] = useState("CALL_NOTE"); const [noteContent, setNoteContent] = useState(""); const [noteBusy, setNoteBusy] = useState(false); const validation = proposal.validation || { blockers: [], warnings: [] }; const forms = proposal.forms_v2 || {}; const readiness = proposal.intake_readiness || { ready: false, blockers: validation.blockers || [], warnings: validation.warnings || [] }; const [contactDraft, setContactDraft] = useState({ display_name: forms.proposal_contact?.display_name || fields.attn_contact || "", email: forms.proposal_contact?.email || fields.contact_email || "", mobile: forms.proposal_contact?.mobile || fields.mobile_no || "" }); const [siteDraft, setSiteDraft] = useState({ location_text: forms.site_context?.location_text || fields.location || "", plot_text: forms.site_context?.plot_text || "", area_value: forms.site_context?.area_value || "", area_unit: forms.site_context?.area_unit || "m2", area_kind: forms.site_context?.area_kind || "LEGACY_UNSPECIFIED", site_description: forms.site_context?.site_description || "" }); const [scopeDescription, setScopeDescription] = useState("");
  const [savedAt, setSavedAt] = useState(""); const [dirty, setDirty] = useState(false); const [stakeholderRole, setStakeholderRole] = useState("OWNER"); const [stakeholderName, setStakeholderName] = useState(""); const [unknownText, setUnknownText] = useState(""); const [conflictText, setConflictText] = useState(""); const [responseType, setResponseType] = useState("PENDING"); const [responseNotes, setResponseNotes] = useState(""); const [outcome, setOutcome] = useState("WON");
  const update = (key: string, value: string) => { setDirty(true); setFields((current: any) => ({ ...current, [key]: value, provenance: { ...(current.provenance || {}), [key]: "manual" } })); };
  useEffect(() => { const guard = (event: BeforeUnloadEvent) => { if (dirty) { event.preventDefault(); event.returnValue = ""; } }; window.addEventListener("beforeunload", guard); return () => window.removeEventListener("beforeunload", guard); }, [dirty]);
  const save = async () => { setSaving(true); setError(""); try { const editableFields = role === "RESPONSIBLE_ENGINEER" ? Object.fromEntries(Object.entries(fields).filter(([key]) => technicalKeys.has(key))) : fields; const result = await api<any>(`/api/bd/proposals/${proposal.id}`, { method: "PATCH", headers: { ...headers(role), "Content-Type": "application/json" }, body: JSON.stringify({ fields: editableFields, expected_updated_at: proposal.updated_at, ...(role === "RESPONSIBLE_ENGINEER" ? {} : { amec_input: JSON.parse(amec || "{}") }) }) }); setProposal(result); setDirty(false); setSavedAt(new Date().toLocaleTimeString()); setMessage(role === "RESPONSIBLE_ENGINEER" ? "Engineering technical preparation saved." : "Proposal fields and AMEC Input saved."); } catch (cause) { setError(cause instanceof Error ? cause.message : "Proposal fields could not be saved; reload and retry."); } finally { setSaving(false); } };
  const upload = async (sourceType: SourceType, file: File | null) => { if (!file) return; setSourceBusy(sourceType); setError(""); const form = new FormData(); form.append("source_type", sourceType); form.append("file", file); try { const result = await api<any>(`/api/bd/proposals/${proposal.id}/sources`, { method: "POST", headers: headers(role), body: form }); setProposal(result.proposal); setMessage(`${sourceType.replaceAll("_", " ")} registered and read-back verified.`); } catch (cause) { setError(cause instanceof Error ? cause.message : "Source evidence could not be registered."); } finally { setSourceBusy(null); } };
  const validate = async () => { const result = await api<any>(`/api/bd/proposals/${proposal.id}/validation`, { headers: headers(role) }); setProposal((current: any) => ({ ...current, validation: result })); };
  const saveV2 = async (path: string, payload: any, success: string) => { try { const result = await api<any>(`/api/bd/proposals/${proposal.id}/${path}`, { method: path === "contact" || path === "site-context" ? "PUT" : "POST", headers: { ...headers(role), "Content-Type": "application/json" }, body: JSON.stringify(payload) }); setProposal(result); setMessage(success); } catch (cause) { setError(cause instanceof Error ? cause.message : "Proposal governance update failed."); } };
  const confirmRegulatory = async (intentId: string) => { try { const result = await api<any>(`/api/bd/proposals/${proposal.id}/regulatory-scope/${intentId}/confirm`, { method: "POST", headers: headers(role) }); setProposal(result); setMessage("Regulatory scoping intent confirmed for Proposal planning only."); } catch (cause) { setError(cause instanceof Error ? cause.message : "Regulatory scope could not be confirmed."); } };
  const refreshInputs = async () => { try { const result = await api<any>(`/api/bd/proposals/${proposal.id}/expected-client-inputs/preview`, { method: "POST", headers: headers(role) }); setProposal(result); setMessage("Expected Client Inputs — Preliminary refreshed and policy-pinned."); } catch (cause) { setError(cause instanceof Error ? cause.message : "Expected Client Inputs could not be refreshed."); } };
  const addNote = async () => { if (!noteContent.trim()) return; setNoteBusy(true); setError(""); try { const result = await api<any>(`/api/bd/proposals/${proposal.id}/notes`, { method: "POST", headers: { ...headers(role), "Content-Type": "application/json" }, body: JSON.stringify({ note_type: noteType, content: noteContent }) }); setProposal(result); setNoteContent(""); setMessage("Note saved as human-entered context; it is not verified external fact."); } catch (cause) { setError(cause instanceof Error ? cause.message : "Note could not be saved."); } finally { setNoteBusy(false); } };
  const uploadSitePhoto = async (file: File | null) => { if (!file) return; const form = new FormData(); form.append("file", file); setError(""); try { const result = await api<any>(`/api/bd/proposals/${proposal.id}/site-photos`, { method: "POST", headers: headers(role), body: form }); setProposal(result); setMessage("Site / Project Photo registered separately from Tender Photo / Image."); } catch (cause) { setError(cause instanceof Error ? cause.message : "Site photo could not be registered."); } };
  const proceed = async () => { setError(""); try { const result = await api<any>(`/api/bd/proposals/${proposal.id}/proceed`, { method: "POST", headers: headers(role) }); setProposal(result.proposal); setMessage("Proposal Intake completed. Engineering Proposal Preparation is now the next step."); } catch (cause) { setError(cause instanceof Error ? cause.message : "Proceed is blocked by intake readiness."); } };
  const accept = async () => { setError(""); try { const result = await api<any>(`/api/bd/proposals/${proposal.id}/accept`, { method: "POST", headers: headers(role) }); setProposal(result); setMessage(`Revision ${result.current_revision.revision_number} accepted by a human operator.`); } catch (cause) { setError(cause instanceof Error ? cause.message : "Accept is blocked by validation or a stale revision."); } };
  const addStakeholder = async () => { if (!stakeholderName.trim()) return; const result = await saveV2("stakeholders", { role_code: stakeholderRole, display_snapshot: stakeholderName, status: "CANDIDATE" }, "Stakeholder intent recorded; Party identity remains separate."); setStakeholderName(""); return result; };
  const addUnknown = async () => { if (!unknownText.trim()) return; await saveV2("unknowns", { category: "COMMERCIAL", statement: unknownText, materiality: "MATERIAL" }, "Unknown recorded as distinct unresolved information."); setUnknownText(""); };
  const addConflict = async () => { if (!conflictText.trim()) return; await saveV2("conflicts", { field_code: "OWNER_REVIEW", source_a: "Source A", value_a: conflictText, source_b: "Source B", value_b: "Needs comparison", materiality: "MATERIAL" }, "Conflict recorded without silently selecting a winner."); setConflictText(""); };
  const acknowledge = async (target_type: string, target_id: string) => { const result = await api<any>(`/api/bd/proposals/${proposal.id}/acknowledgments`, { method: "POST", headers: { ...headers(role), "Content-Type": "application/json" }, body: JSON.stringify({ target_type, target_id }) }); setProposal(result); setMessage("Material risk acknowledged by a human; acknowledgement is not resolution."); };
  const reviewStaleness = async () => { const result = await api<any>(`/api/bd/proposals/${proposal.id}/staleness/review`, { method: "POST", headers: headers(role) }); setProposal(result); setMessage("Source/configuration change reviewed; affected Proposal sections remain visible."); };
  const createRevision = async () => { const result = await api<any>(`/api/bd/proposals/${proposal.id}/revisions`, { method: "POST", headers: { ...headers(role), "Content-Type": "application/json" }, body: JSON.stringify({ reason: "Post-Accept change or Client Change Requested" }) }); setProposal(result.proposal); setMessage(`Working Proposal revision R${result.revision.revision_number} created from accepted history.`); };
  const recordResponse = async () => { const result = await api<any>(`/api/bd/proposals/${proposal.id}/client-responses`, { method: "POST", headers: { ...headers(role), "Content-Type": "application/json" }, body: JSON.stringify({ response_type: responseType, notes: responseNotes, idempotency_key: `browser-response-${proposal.id}-${responseType}` }) }); setProposal(result.proposal); setMessage(`Client Response ${responseType.replaceAll("_", " ")} recorded with human evidence.`); };
  const recordOutcome = async () => { const result = await api<any>(`/api/bd/proposals/${proposal.id}/commercial-outcome`, { method: "POST", headers: { ...headers(role), "Content-Type": "application/json" }, body: JSON.stringify({ outcome, reason: "Recorded through Proposal workspace" }) }); setProposal(result.proposal); setMessage(`Commercial outcome ${outcome} recorded separately from Ready / Close.`); };
  const sourceByType = useMemo(() => Object.fromEntries((proposal.sources || []).map((item: any) => [item.source_type, item])), [proposal.sources]);
  const fieldDisabled = (key: string) => readOnly && !technicalKeys.has(key);
  return <>
    <div className="page-intro"><div><span className="eyebrow">PROPOSAL INTAKE</span><h2>{proposal.title}</h2><p>Proposal {proposal.proposal_reference} · {proposal.project_reference || "Opportunity Ref provisional"}</p><p className="muted">Current owner: {proposal.current_owner || "Business Development"} · Next: {proposal.next_action?.label || "Review Proposal"}</p></div><button className="text-button" onClick={onBack}>← Proposals</button></div>
    <div className="workflow-stepper opportunity-tabs" aria-label="Proposal lifecycle">{lifecycleLabels.map((label, index) => <div className={`workflow-step ${proposal.lifecycle?.[index]?.active ? "active" : ""}`} key={label}><span className="workflow-step-dot">{index + 1}</span><span>{label}</span></div>)}</div>
    {message && <div className="inline-message" role="status">{message}</div>}{error && <div className="error-state" role="alert">{error}</div>}
    <section className="panel bd-workspace-header"><div><small>Proposal</small><b>{proposal.proposal_reference}</b></div><div><small>Opportunity Ref</small><b>{proposal.project_reference || "Provisional"}</b></div><div><small>Stage</small><b>{proposal.stage_label}</b></div><div><small>Current owner</small><b>{proposal.current_owner || "Business Development"}</b></div><div><small>Revision</small><b>{proposal.current_revision ? `AMEC Accepted r${proposal.current_revision.revision_number}` : "Draft intake"}</b></div><div><small>Draft save</small><b>{dirty ? "Unsaved local edits" : savedAt ? `Saved ${savedAt}` : "Saved state loaded"}</b></div></section>
    {proposal.hardening?.active_staleness?.length ? <section className="panel bd-stale-panel"><div className="panel-head"><div><span className="eyebrow">NEEDS REVIEW</span><h3>Source or governed input changed</h3></div><button className="button-secondary" onClick={() => void reviewStaleness()} disabled={readOnly}>Review and clear active change</button></div><p>Human-entered work was not silently overwritten. Review these impacted sections before Accept:</p><div className="bd-gap-list warning">{proposal.hardening.active_staleness.map((item: any) => <span key={item.id}>{item.reason_code} · {(item.impacted_sections || []).join(", ")}</span>)}</div></section> : null}
    {proposal.hardening?.current_information_changed ? <section className="panel bd-stale-panel"><div className="panel-head"><div><span className="eyebrow">HISTORICAL INTEGRITY</span><h3>Current information has changed since this Proposal was accepted</h3></div><span className="provenance-badge warning">NEW REVISION RECOMMENDED</span></div><p>Accepted revision {proposal.current_revision?.revision_number} remains immutable. Current fields, sources, stakeholders, or governed content differ from that historical snapshot.</p>{!readOnly && <button className="button-secondary" onClick={() => void createRevision()}>Create new Proposal revision</button>}</section> : null}
    <ProposalConfigurationPanel configuration={proposal.configuration} role={role} />
    <div className="bd-workspace-grid"><section className="panel"><div className="panel-head"><div><span className="eyebrow">TENDER &amp; CLIENT SOURCES</span><h3>Sources</h3></div><small>Received: {proposal.intake_readiness?.source_count || 0} · evidence is not verified fact</small></div><div className="bd-source-grid">{sourceTypes.map((item) => <label className={`bd-source-card ${sourceByType[item.key] ? "complete" : ""}`} key={item.key}><b>{item.label}</b><small>{sourceByType[item.key] ? `✓ Received · ${sourceByType[item.key].verification_state}` : "Available source type · not required unless configured"}</small>{!readOnly && <input type="file" aria-label={`Add ${item.label}`} onChange={(event) => void upload(item.key, event.target.files?.[0] || null)} disabled={sourceBusy === item.key} />}</label>)}</div><p className="muted">Site / Project Photos remain separate from Tender Photo / Image. Source history, hashes, DocumentVersion links, and provenance remain available in History.</p></section>
      <section className="panel bd-v2-section"><div className="panel-head"><div><span className="eyebrow">CLIENT &amp; CONTACTS</span><h3>Commercial Client and Proposal Contact</h3></div><small>Commercial contact is not an Applicant or legal signatory.</small></div><p><b>{forms.commercial_client?.display_name || fields.client_name || "Commercial Client not recorded"}</b>{forms.commercial_client?.canonical_party_id ? <span className="provenance-badge">Canonical Party linked</span> : <span className="provenance-badge warning">Party resolution pending</span>}</p><div className="bd-form-grid"><label>Proposal Contact<input value={contactDraft.display_name} onChange={(event) => setContactDraft({ ...contactDraft, display_name: event.target.value })} disabled={readOnly} /></label><label>Email<input value={contactDraft.email} onChange={(event) => setContactDraft({ ...contactDraft, email: event.target.value })} disabled={readOnly} /></label><label>Mobile<input value={contactDraft.mobile} onChange={(event) => setContactDraft({ ...contactDraft, mobile: event.target.value })} disabled={readOnly} /></label></div>{!readOnly && <button className="button-secondary" onClick={() => void saveV2("contact", contactDraft, "Proposal contact saved.")}>Save Proposal Contact</button>}</section>
      <section className="panel bd-v2-section"><div className="panel-head"><div><span className="eyebrow">SITE / PROPERTY</span><h3>Site / Property context</h3></div><small>{forms.site_context?.status === "LINKED" ? "Linked canonical Property" : "Unresolved context is allowed in intake"}</small></div><div className="bd-form-grid"><label>Location<input value={siteDraft.location_text} onChange={(event) => setSiteDraft({ ...siteDraft, location_text: event.target.value })} disabled={readOnly} /></label><label>Plot / Property text<input value={siteDraft.plot_text} onChange={(event) => setSiteDraft({ ...siteDraft, plot_text: event.target.value })} disabled={readOnly} /></label><label>Area / quantity basis<input value={siteDraft.area_value} onChange={(event) => setSiteDraft({ ...siteDraft, area_value: event.target.value })} disabled={readOnly} /></label><label>Area kind<select value={siteDraft.area_kind} onChange={(event) => setSiteDraft({ ...siteDraft, area_kind: event.target.value })} disabled={readOnly}><option>LEGACY_UNSPECIFIED</option><option>PLOT_AREA</option><option>GFA</option><option>BUILT_UP_AREA</option><option>NET_AREA</option><option>APPROVED_AREA</option></select></label><label className="wide">Site description<textarea value={siteDraft.site_description} onChange={(event) => setSiteDraft({ ...siteDraft, site_description: event.target.value })} disabled={readOnly} /></label></div><p className="muted">{forms.site_context?.property ? `Linked Property · ${forms.site_context.property.pin || forms.site_context.property.plot_number}` : "No canonical Property has been fabricated from free text."}</p>{!readOnly && <button className="button-secondary" onClick={() => void saveV2("site-context", { ...siteDraft, area_value: siteDraft.area_value === "" ? null : Number(siteDraft.area_value), status: "UNRESOLVED" }, "Site / Property context saved.")}>Save Site / Property context</button>}<label className="site-photo-picker">Site / Project Photos<input type="file" accept="image/*" aria-label="Add Site or Project Photo" onChange={(event) => void uploadSitePhoto(event.target.files?.[0] || null)} disabled={readOnly} /></label>{proposal.site_photos?.length ? <small>{proposal.site_photos.length} site photo(s) registered · separate from Tender Photo / Image</small> : <small>No Site / Project Photos registered.</small>}</section>
      <section className="panel bd-v2-section"><div className="panel-head"><div><span className="eyebrow">STAKEHOLDERS</span><h3>Known / Candidate Stakeholders</h3></div><small>Proposal intent only · no case-role assignment</small></div>{forms.stakeholders?.length ? <div className="bd-v2-list">{forms.stakeholders.map((item: any) => <div key={item.id}><b>{String(item.role_code || "Role pending").replaceAll("_", " ")}</b><span>{item.party?.name_en || item.display_snapshot || "Unknown"}</span><span className="provenance-badge">{String(item.status || "UNAVAILABLE").replaceAll("_", " ")}</span></div>)}</div> : <p className="muted">No stakeholder intent rows recorded.</p>}</section>
      <section className="panel bd-v2-section"><div className="panel-head"><div><span className="eyebrow">AMEC SERVICE SCOPE</span><h3>Structured scope + narrative SOW</h3></div><small>AMEC offering, discipline, and regulatory ServiceType remain distinct.</small></div>{forms.service_scope_items?.length ? <div className="bd-v2-list">{forms.service_scope_items.map((item: any) => <div key={item.id}><b>{item.included ? "Included" : "Excluded"}</b><span>{item.description}</span><small>{item.service_offering_code || "Service offering pending"} · {item.discipline_code || "Discipline pending"}</small></div>)}</div> : <p className="muted">No structured scope rows yet; the narrative SOW remains preserved below.</p>}{!readOnly && <div className="bd-inline-add"><input aria-label="New service scope item" placeholder="Add AMEC service scope item" value={scopeDescription} onChange={(event) => setScopeDescription(event.target.value)} /><button className="button-secondary" onClick={() => { if (scopeDescription.trim()) { void saveV2("scope-items", { description: scopeDescription, included: true, commercial_treatment: "AMEC_FEE" }, "AMEC service scope added."); setScopeDescription(""); } }}>Add scope item</button></div>}</section>
      <section className="panel bd-v2-section"><div className="panel-head"><div><span className="eyebrow">STAKEHOLDERS</span><h3>Known, expected, and unresolved parties</h3></div><small>Stakeholder role is not Party identity; no Party is created by a name.</small></div>{proposal.hardening?.stakeholders?.length ? <div className="bd-v2-list">{proposal.hardening.stakeholders.map((item: any) => <div key={item.id}><b>{item.role_code}</b><span>{item.party?.name_en || item.display_snapshot || "Unresolved stakeholder"}</span><small>{item.status} · {item.party_id ? "Canonical Party linked" : "Candidate / expected only"}</small></div>)}</div> : <p className="muted">No stakeholder intent recorded. This section remains progressive and does not require every role.</p>}{!readOnly && <div className="bd-inline-add"><select aria-label="Stakeholder role" value={stakeholderRole} onChange={(event) => setStakeholderRole(event.target.value)}><option>OWNER</option><option>APPLICANT</option><option>CONSULTANT</option><option>TENANT</option><option>BUYER</option><option>REPRESENTATIVE</option><option>CONTRACTOR</option></select><input aria-label="Stakeholder name or unresolved description" placeholder="Known name or expected stakeholder" value={stakeholderName} onChange={(event) => setStakeholderName(event.target.value)} /><button className="button-secondary" onClick={() => void addStakeholder()}>Add stakeholder</button></div>}</section>
      <section className="panel bd-v2-section"><div className="panel-head"><div><span className="eyebrow">REGULATORY SCOPING · COMMERCIAL PLANNING</span><h3>Regulatory Scoping</h3></div><small>Preliminary commercial intent only · not an AuthorityCase or government determination.</small></div>{forms.regulatory_scope_intents?.length ? <div className="bd-v2-list">{forms.regulatory_scope_intents.map((item: any) => <div key={item.id}><b>{item.external_body || "Body pending"}</b><span>{item.service_type || "Service pending"}{item.jurisdiction ? ` · ${item.jurisdiction}` : ""}</span><span className="provenance-badge">{String(item.status || "UNAVAILABLE").replaceAll("_", " ")}</span>{!readOnly && item.status !== "HUMAN_CONFIRMED_FOR_PROPOSAL" && <button className="text-button" onClick={() => void confirmRegulatory(item.id)}>Confirm for Proposal</button>}</div>)}</div> : <p className="muted">Regulatory scope is currently unknown. Add a canonical intent when commercial planning supports it.</p>}</section>
      <section className="panel bd-v2-section"><div className="panel-head"><div><span className="eyebrow">EXPECTED CLIENT INPUTS</span><h3>Expected Client Inputs — Preliminary</h3></div><button className="text-button" onClick={() => void refreshInputs()} disabled={readOnly}>Refresh preview</button></div>{forms.expected_client_inputs ? <><p><span className="provenance-badge">{forms.expected_client_inputs.status.replaceAll("_", " ")}</span> {forms.expected_client_inputs.result_items?.length || 0} preliminary item(s)</p><small className="muted">Policy versions and evaluation time are pinned in details; this is not an authority checklist.</small></> : <p className="muted">No preliminary client-input preview has been generated.</p>}</section>
      <section className="panel"><div className="panel-head"><div><span className="eyebrow">CLIENT REQUEST</span><h3>Client Request</h3></div><small>Client Requested Scope ≠ AMEC Scope · Client Budget ≠ AMEC Proposal Price · Requested Timing ≠ Commercial Duration</small></div><div className="bd-form-grid"><label>Commercial Client<input value={fields.client_name || ""} onChange={(event) => update("client_name", event.target.value)} disabled={readOnly} /></label><label>Proposal Contact<input value={fields.attn_contact || ""} onChange={(event) => update("attn_contact", event.target.value)} disabled={readOnly} /></label><label className="wide">Project / Proposal Description<input value={fields.project_description || ""} onChange={(event) => update("project_description", event.target.value)} disabled={readOnly} /></label><label className="wide">Client Requested Scope<textarea value={fields.client_scope_of_work || ""} onChange={(event) => update("client_scope_of_work", event.target.value)} disabled={readOnly} /></label><label>Client Budget / Budget Indication<input value={fields.client_budget || ""} onChange={(event) => update("client_budget", event.target.value)} disabled={readOnly} placeholder="Not supplied" /></label><label>Requested Timing / Deadline<input value={fields.requested_timing || ""} onChange={(event) => update("requested_timing", event.target.value)} disabled={readOnly} placeholder="Not supplied" /></label><label className="wide">Client exclusions / constraints<textarea value={fields.client_constraints || ""} onChange={(event) => update("client_constraints", event.target.value)} disabled={readOnly} /></label><label className="wide">Additional Information<textarea value={fields.additional_information || ""} onChange={(event) => update("additional_information", event.target.value)} disabled={readOnly} /></label><label className="wide">AMEC Scope of Work (SOW) · Engineering Preparation<textarea value={fields.scope_of_work || fields.sow || ""} onChange={(event) => update("scope_of_work", event.target.value)} disabled={fieldDisabled("scope_of_work")} /></label><label className="wide">Process of Work · Engineering Preparation<textarea value={fields.process_of_work || ""} onChange={(event) => update("process_of_work", event.target.value)} disabled={fieldDisabled("process_of_work")} /></label><label>AMEC Proposal Price<input value={fields.price || ""} onChange={(event) => update("price", event.target.value)} disabled={readOnly} placeholder="Not recorded" /></label><label>Currency<input value={fields.currency || "QAR"} onChange={(event) => update("currency", event.target.value)} disabled={readOnly} /></label><label>Commercial Duration<input value={fields.duration || fields.period || ""} onChange={(event) => update("duration", event.target.value)} disabled={readOnly} placeholder="Later commercial review" /></label></div>{!readOnly && <button className="button-secondary" onClick={() => void save()} disabled={saving}>{saving ? "Saving…" : "Save client request"}</button>}{readOnly && <button className="button-secondary" onClick={() => void save()} disabled={saving}>{saving ? "Saving…" : "Save technical preparation"}</button>}</section>
      <section className="panel bd-v2-section"><div className="panel-head"><div><span className="eyebrow">ENGINEERING PREPARATION</span><h3>AMEC Scope, Process of Work &amp; Technical Inputs</h3></div><small>Engineering edits technical preparation. BD retains read access; commercial fields remain BD-controlled.</small></div><div className="bd-summary-grid"><div><b>AMEC Scope of Work (SOW)</b><p>{fields.scope_of_work || fields.sow || "Not recorded"}</p></div><div><b>Process of Work</b><p>{fields.process_of_work || "Not recorded"}</p></div></div>{forms.engineering_contributions?.length ? <div className="bd-v2-list">{forms.engineering_contributions.map((item: any) => <div key={item.id}><b>{String(item.contribution_type || "Technical contribution").replaceAll("_", " ")}</b><span>{item.content || "Content unavailable"}</span><small>{item.discipline_code || "Technical input"} · {item.contributed_by || "Contributor unavailable"}</small></div>)}</div> : <p className="muted">No separate Engineering contribution rows recorded yet.</p>}{forms.proposal_form?.length ? <div className="bd-v2-list"><div><b>Proposal Form · existing Proposal context</b><span>{forms.proposal_form[0].filename || "Filename unavailable"}</span><small>{forms.proposal_form[0].verification_state || "Verification unavailable"} · source version {forms.proposal_form[0].source_revision || "not labelled"}</small></div></div> : <p className="muted">No Proposal Form artifact is currently linked. It belongs here when supplied, not in New Proposal intake.</p>}</section>
      <section className="panel bd-v2-section"><div className="panel-head"><div><span className="eyebrow">COMMERCIAL</span><h3>Price, Duration, Inclusions &amp; Exclusions</h3></div><small>AMEC Fee is distinct from External / Pass-through Costs; commercial edit authority remains with BD.</small></div><div className="bd-summary-grid"><div><b>AMEC Fee</b><p>{fields.price || "Not set"} {fields.currency || "QAR"}</p></div><div><b>Currency</b><p>{fields.currency || "QAR · safe default"}</p></div><div><b>Payment Terms</b><p>{fields.payment_terms || fields.payment_condition || "Not recorded"}</p></div><div><b>AMEC Delivery Duration</b><p>{fields.duration || fields.period || "Not set"}</p></div><div><b>Proposal Validity</b><p>{fields.proposal_validity || "Owner policy/content pending"}</p></div><div><b>Inclusions</b><p>{Array.isArray(fields.inclusions) ? fields.inclusions.join(", ") : fields.inclusions || "Not recorded"}</p></div><div><b>Exclusions</b><p>{Array.isArray(fields.exclusions) ? fields.exclusions.join(", ") : fields.exclusions || "Not recorded"}</p></div></div>{forms.external_cost_assumptions?.length ? <div className="bd-v2-list">{forms.external_cost_assumptions.map((item: any) => <div key={item.id}><b>External / Pass-through · {String(item.treatment || "Treatment unavailable").replaceAll("_", " ")}</b><span>{item.description || "Description unavailable"}</span><small>{item.estimated_amount || "Amount unknown"} {item.currency || fields.currency || "QAR"} · estimate/assumption, not Contract truth</small></div>)}</div> : <p className="muted">No configured External / Pass-through Cost category. AMEC Fee remains separate.</p>}</section>
      <section className="panel bd-v2-section"><div className="panel-head"><div><span className="eyebrow">PROPOSAL BREAKDOWN</span><h3>Proposal Breakdown</h3></div><small>Projection over current structured scope, Engineering contributions, external-cost assumptions, and technical deliverables.</small></div>{proposal.proposal_breakdown?.items?.length ? <div className="bd-v2-list">{proposal.proposal_breakdown.items.map((item: any) => <div key={item.id}><b>{item.kind}</b><span>{item.label}{item.detail ? ` · ${item.detail}` : ""}</span><small>{item.source}{item.included === false ? " · Excluded" : ""}</small></div>)}</div> : <p className="muted">No structured Proposal Breakdown items recorded yet.</p>}<div className="bd-summary-grid"><div><b>Commercial summary</b><p>{proposal.proposal_breakdown?.commercial_summary?.price || "Not set"} {proposal.proposal_breakdown?.commercial_summary?.currency || "QAR"} · {proposal.proposal_breakdown?.commercial_summary?.duration || "Duration not set"}</p></div><div><b>Lineage</b><p>Current Proposal truth · no duplicate breakdown master</p></div></div></section>
      <section className="panel bd-v2-section"><div className="panel-head"><div><span className="eyebrow">ASSUMPTIONS · UNKNOWNS · CONFLICTS</span><h3>Decision context</h3></div><small>Distinct records with materiality. Acknowledged does not mean resolved.</small></div><div className="bd-v2-list">{(forms.assumptions || []).map((item: any) => <div key={item.id}><b>Assumption · {item.materiality}</b><span>{item.statement}</span><small>{item.status} · {item.acknowledged_by ? `Acknowledged by ${item.acknowledged_by}` : "Acknowledgment pending"}{item.materiality === "MATERIAL" && !item.acknowledged_by && !readOnly && <button className="text-button" onClick={() => void acknowledge("PROPOSAL_ASSUMPTION", item.id)}>Acknowledge risk</button>}</small></div>)}{(proposal.hardening?.unknowns || []).map((item: any) => <div key={item.id}><b>Unknown · {item.materiality}</b><span>{item.statement}</span><small>{item.status} · {item.acknowledged ? "Acknowledged" : "Unresolved"}{item.materiality !== "INFORMATIONAL" && !item.acknowledged && !readOnly && <button className="text-button" onClick={() => void acknowledge("PROPOSAL_UNKNOWN", item.id)}>Acknowledge risk</button>}</small></div>)}{(proposal.hardening?.conflicts || []).map((item: any) => <div key={item.id}><b>Conflict · {item.field_code}</b><span>{item.source_a}: {item.value_a || "—"} · {item.source_b}: {item.value_b || "—"}</span><small>{item.status} · {item.acknowledged ? "Acknowledged" : "Resolution/acknowledgment pending"}{item.materiality !== "INFORMATIONAL" && !item.acknowledged && !readOnly && <button className="text-button" onClick={() => void acknowledge("PROPOSAL_CONFLICT", item.id)}>Acknowledge risk</button>}</small></div>)}</div>{!forms.assumptions?.length && !proposal.hardening?.unknowns?.length && !proposal.hardening?.conflicts?.length && <p className="muted">No assumptions, unknowns, or conflicts recorded.</p>}{!readOnly && <div className="bd-inline-add"><input aria-label="New Proposal unknown" placeholder="Add unresolved unknown" value={unknownText} onChange={(event) => setUnknownText(event.target.value)} /><button className="button-secondary" onClick={() => void addUnknown()}>Add unknown</button><input aria-label="New Proposal conflict" placeholder="Add source conflict summary" value={conflictText} onChange={(event) => setConflictText(event.target.value)} /><button className="button-secondary" onClick={() => void addConflict()}>Add conflict</button></div>}</section>
      <section className="panel bd-v2-section"><div className="panel-head"><div><span className="eyebrow">NOTES &amp; CLIENT CONVERSATIONS</span><h3>Human-entered context</h3></div><small>Notes remain unverified context unless explicitly verified or accepted as an assumption.</small></div>{proposal.notes?.length ? <div className="bd-v2-list">{proposal.notes.map((note: any) => <div key={note.id}><b>{String(note.note_type || "Note").replaceAll("_", " ")}</b><span>{note.content || "No note content recorded"}</span><small>{note.entered_by || "Operator unavailable"} · {note.created_at ? new Date(note.created_at).toLocaleString() : "Date unavailable"} · {String(note.status || "UNAVAILABLE").replaceAll("_", " ")}</small></div>)}</div> : <p className="muted">No client conversation notes recorded.</p>}{!readOnly && <div className="bd-inline-add"><select aria-label="Note type" value={noteType} onChange={(event) => setNoteType(event.target.value)}><option value="CALL_NOTE">Call Note</option><option value="MEETING_NOTE">Meeting Note</option><option value="CLIENT_CLARIFICATION">Client Clarification</option><option value="INTERNAL_INTAKE">Internal Intake Note</option></select><input aria-label="Note content" placeholder="Record the conversation or clarification" value={noteContent} onChange={(event) => setNoteContent(event.target.value)} /><button className="button-secondary" onClick={() => void addNote()} disabled={noteBusy}>{noteBusy ? "Saving…" : "Add note"}</button></div>}</section>
      <section className="panel intake-readiness-panel"><div className="panel-head"><div><span className="eyebrow">INTAKE READINESS</span><h3>{readiness.ready ? "Ready for Engineering" : "Complete intake before Engineering"}</h3></div><button className="text-button" onClick={() => void validate()}>Recheck</button></div>{(readiness.blockers || []).length ? <div className="bd-gap-list blocker">{readiness.blockers.map((item: any) => <span key={item.code}>⚠ {item.label}</span>)}</div> : <div className="bd-gap-list"><span>✓ Client context sufficient</span><span>✓ Source evidence received and verified</span><span>✓ Proposal description captured</span><span>✓ Reference state valid</span></div>}{(readiness.warnings || []).map((item: any) => <div className="bd-gap-list warning" key={item.code}><span>⚠ {item.label}</span></div>)}{proposal.stage === "IN_REVIEW" || proposal.stage === "RECEIVED" ? <button className="button-primary" onClick={() => void proceed()} disabled={readOnly || !readiness.ready}>Proceed to Engineering Preparation</button> : <p className="muted">Next owner: {proposal.next_actor || "Engineering"}. The same Proposal identity continues through preparation.</p>}</section>
      <section className="panel bd-v2-section"><div className="panel-head"><div><span className="eyebrow">INFORMATION &amp; AMEC INPUT</span><h3>Information &amp; AMEC Input</h3></div><small>Additional Information is Proposal context. AMEC Input is internal AMEC contribution and is not client-visible by default.</small></div><div className="bd-summary-grid"><div><b>Additional Information</b><p>{proposal.additional_information || fields.additional_information || "Not recorded"}</p></div><div><b>Visibility</b><p>AMEC internal · entered by the current human operator · retained in accepted revision snapshots</p></div></div><label className="bd-amec-label">AMEC Input<textarea className="bd-amec-input" value={amec} onChange={(event) => setAmec(event.target.value)} disabled={readOnly} /></label><p className="muted">Separate from Tender/client notes and from AMEC Scope / Process of Work. AI assist is disabled; no autonomous acceptance is generated.</p>{!readOnly && <button className="button-secondary" onClick={() => void save()}>Save AMEC Input</button>}</section>
      <section className="panel bd-v2-section"><div className="panel-head"><div><span className="eyebrow">CLIENT RESPONSE</span><h3>Client Response</h3></div><small>Recorded human evidence · separate from AMEC Proposal Accept and Contract execution.</small></div>{proposal.hardening?.client_responses?.length ? <div className="bd-v2-list">{proposal.hardening.client_responses.map((item: any) => <div key={item.id}><b>{String(item.response_type || "Response unavailable").replaceAll("_", " ")}</b><span>{item.notes || "No notes recorded"}</span><small>{item.recorded_by || "Operator unavailable"} · {item.recorded_at ? new Date(item.recorded_at).toLocaleString() : "Date unavailable"} · {item.accepted_revision_id || "revision not pinned"}</small></div>)}</div> : <p className="muted">No external Client Response recorded.</p>}{!readOnly && <div className="bd-inline-add"><select aria-label="Client Response type" value={responseType} onChange={(event) => setResponseType(event.target.value)}><option>PENDING</option><option>ACCEPTED</option><option>DECLINED</option><option>CHANGE_REQUESTED</option><option>EXPIRED</option><option>WITHDRAWN</option></select><input aria-label="Client Response evidence notes" placeholder="Evidence / notes / source" value={responseNotes} onChange={(event) => setResponseNotes(event.target.value)} /><button className="button-secondary" onClick={() => void recordResponse()}>Record response</button></div>}{responseType === "CHANGE_REQUESTED" && proposal.current_revision && !readOnly && <button className="text-button" onClick={() => void createRevision()}>Create new revision from accepted history →</button>}</section>
      <section className="panel bd-v2-section"><div className="panel-head"><div><span className="eyebrow">COMMERCIAL OUTCOME</span><h3>Outcome separate from Ready / Close</h3></div><small>Won, Lost, Withdrawn, Expired, Converted, and Superseded remain evidence-recorded business outcomes.</small></div><p>{proposal.hardening?.commercial_outcome ? `${proposal.hardening.commercial_outcome.outcome} · ${proposal.hardening.commercial_outcome.reason || "No reason recorded"}` : "No final commercial outcome recorded."}</p>{!readOnly && <div className="bd-inline-add"><select aria-label="Commercial outcome" value={outcome} onChange={(event) => setOutcome(event.target.value)}><option>WON</option><option>LOST</option><option>WITHDRAWN</option><option>EXPIRED</option><option>CONVERTED</option><option>SUPERSEDED</option></select><button className="button-secondary" onClick={() => void recordOutcome()}>Record outcome</button></div>}</section>
      <section className="panel bd-accept-review-panel"><div className="panel-head"><div><span className="eyebrow">ACCEPT REVIEW · EXACT REVISION CANDIDATE</span><h3>One concise human decision view</h3></div><span className={`provenance-badge ${validation.blockers?.length ? "warning" : ""}`}>{validation.blockers?.length ? `${validation.blockers.length} blocker(s)` : "No blocking item"}</span></div><div className="bd-summary-grid"><div><b>Client / Contact</b><p>{forms.commercial_client?.display_name || fields.client_name || "Not recorded"} · {forms.proposal_contact?.display_name || fields.attn_contact || "Contact pending"}</p></div><div><b>Site / Property</b><p>{forms.site_context?.location_text || fields.location || "Not recorded"} · {forms.site_context?.area_value ? `${forms.site_context.area_value} ${forms.site_context.area_unit || "unit"} (${forms.site_context.area_kind})` : "Area basis pending"}</p></div><div><b>AMEC Scope / Regulatory</b><p>{fields.scope_of_work || fields.sow || "Scope pending"} · {forms.regulatory_scope_intents?.length ? `${forms.regulatory_scope_intents.length} preliminary intent(s)` : "No intent recorded"}</p></div><div><b>Commercial</b><p>{fields.price || "Fee pending"} {fields.currency || "QAR"} · {fields.duration || fields.period || "Duration pending"} · validity {fields.proposal_validity || "pending"}</p></div><div><b>Assumptions / Unknowns / Conflicts</b><p>{(forms.assumptions?.length || 0) + (proposal.hardening?.unknowns?.length || 0) + (proposal.hardening?.conflicts?.length || 0)} recorded · {(proposal.hardening?.material_open_unknowns?.length || 0) + (proposal.hardening?.material_open_conflicts?.length || 0)} material action(s)</p></div><div><b>Expected Inputs / Dashboard</b><p>{forms.expected_client_inputs?.status || "Preview unavailable"} · Template {validation.template?.item ? `v${validation.template.item.version}` : "unresolved"} · Checklist {validation.checklist?.item ? `v${validation.checklist.item.version}` : "unresolved"}</p></div></div><p className="muted">Accept checks the exact current Proposal revision, source freshness, policy applicability, material acknowledgments, Dashboard readiness, and human Authority. No government AuthorityCase is created.</p></section>
      <section className="panel bd-authority-panel"><div className="panel-head"><div><span className="eyebrow">REVIEW / AUTHORITY</span><h3>Proposal Review / Authority</h3></div><span className={`provenance-badge ${proposal.authority?.status === "BLOCKED" ? "warning" : ""}`}>{proposal.authority?.status_label || "Review status not available"}</span></div><div className="bd-summary-grid"><div><b>Required authority</b><p>{proposal.authority?.required_authority || "Configured Proposal authority"}</p></div><div><b>Current reviewer / capability</b><p>{proposal.authority?.current_reviewer || "Business Development"}</p></div><div><b>Readiness blockers</b><p>{proposal.authority?.readiness_blockers?.length ? proposal.authority.readiness_blockers.map((item: any) => item.label).join(" · ") : "None"}</p></div><div><b>Last review decision</b><p>{proposal.authority?.last_review_decision || "No human Proposal review recorded"}</p></div></div><p className="muted">This is human commercial Proposal authority, not government authority and not an AuthorityCase.</p></section>
      <section className="panel"><div className="panel-head"><div><span className="eyebrow">READINESS &amp; GAPS</span><h3>{validation.ready ? "Ready for human Accept" : "Action required"}</h3></div><button className="text-button" onClick={() => void validate()}>Revalidate</button></div>{validation.blockers?.length ? <div className="bd-gap-list blocker"><b>Blockers</b>{validation.blockers.map((item: any) => <span key={item.code}>• {item.label}</span>)}</div> : <div className="inline-message">No blockers.</div>}{validation.warnings?.length ? <div className="bd-gap-list warning"><b>Warnings</b>{validation.warnings.map((item: any) => <span key={item.code}>• {item.label}</span>)}</div> : null}<p className="muted">Template: {validation.template?.item ? `${validation.template.item.ref} v${validation.template.item.version}` : "unresolved"} · Checklist: {validation.checklist?.item ? `${validation.checklist.item.ref} v${validation.checklist.item.version}` : "unresolved"}</p></section>
      <section className="panel bd-review-panel"><div><span className="eyebrow">ACCEPT / OUTPUTS</span><h3>Accept → Proposal Download + Checklist Download</h3><p>Human Accept freezes this exact Proposal state and current Dashboard versions into an immutable Accepted Proposal revision.</p></div>{!readOnly && <button className="button-primary" onClick={() => void accept()} disabled={!validation.ready || proposal.authority?.status === "BLOCKED"}>Accept Proposal</button>}<div className="bd-output-links">{proposal.outputs?.available ? <><a className="text-button" download={proposal.outputs.proposal?.filename} href={`/api/bd/proposals/${proposal.id}/outputs/proposal`}>Proposal Download</a><a className="text-button" download={proposal.outputs.checklist?.filename} href={`/api/bd/proposals/${proposal.id}/outputs/checklist`}>Checklist Download</a><a className="text-button" href={`/api/bd/proposals/${proposal.id}/handoff/contract`}>View Contract eligibility</a></> : <span className="muted">Outputs: Proposal and Checklist become available after human Accept.</span>}</div>{proposal.current_revision && <small className="muted">Accepted revision {proposal.current_revision.revision_number} · Proposal {proposal.current_revision.template.ref} v{proposal.current_revision.template.version} · Checklist {proposal.current_revision.checklist.ref} v{proposal.current_revision.checklist.version}</small>}</section>
      <section className="panel"><div className="panel-head"><div><span className="eyebrow">HISTORY / LINEAGE</span><h3>Accepted revision history</h3></div><small>{proposal.sources?.length || 0} source record(s) · immutable snapshots retained</small></div>{proposal.revision_history?.length ? <div className="bd-history-list">{proposal.revision_history.map((item: any) => <div className="bd-history-row" key={item.id}><b>Revision {item.revision_number}</b><span>{item.accepted_by || "Operator unavailable"}</span><span>{item.accepted_at ? new Date(item.accepted_at).toLocaleString() : "Date unavailable"}</span><code>{String(item.content_hash || "hash unavailable").slice(0, 16)}…</code></div>)}</div> : <p className="muted">No accepted revisions yet.</p>}</section>
    </div>
  </>;
}

function ProposalConfigurationPanel({ configuration, role }: { configuration?: any; role: Role }) {
  const template = configuration?.proposal_template;
  const checklist = configuration?.proposal_checklist;
  const definitions = configuration?.definitions;
  const engineering = configuration?.engineering_references;
  const managedLink = (item?: any) => item?.master_content_id ? `/dashboard?content=${encodeURIComponent(item.master_content_id)}` : "/dashboard";
  const card = (item: any, fallbackLabel: string) => { const resolved = item || { label: fallbackLabel, status: "UNAVAILABLE", message: "Configuration requires attention" }; return <div className="operator-block" key={resolved.label}><b>{resolved.label}</b><span>{resolved.status === "READY" ? `${resolved.ref} v${resolved.version} · Current version` : resolved.message || "Needs Owner confirmation"}</span>{resolved.status === "READY" && <small>Managed in Dashboard · {String(resolved.purpose || "").replaceAll("_", " ")}</small>}{resolved.status !== "READY" && role !== "RESPONSIBLE_ENGINEER" && <a className="text-button" href={managedLink(resolved)}>Manage in Dashboard →</a>}</div>; };
  return <section className="panel proposal-configuration-panel"><div className="panel-head"><div><span className="eyebrow">PROPOSAL CONFIGURATION</span><h3>Managed in Dashboard</h3></div><small>BD consumes governed content; it does not edit the global master.</small></div><div className="two-col">{card(template, "Proposal Template")}{card(checklist, "Proposal Checklist")}</div><div className="two-col"><div className="operator-block"><b>Definitions</b><span>{definitions?.count || 0} applicable semantic definition(s)</span><small>Definitions explain meaning; Proposal fields remain client-specific transaction values.</small><a className="text-button" href="/dashboard#definitions">View definitions in Dashboard →</a></div><div className="operator-block"><b>Engineering references</b><span>{engineering?.status === "DEFERRED" ? "Available during Engineering Preparation" : `${engineering?.items?.length || 0} current eligible reference(s)`}</span><small>Engineering Works are resolved by the backend for the preparation stage.</small>{engineering?.status === "RESOLVED" && <a className="text-button" href="/dashboard">View sources in Dashboard →</a>}</div></div>{configuration?.accepted_revision && <p className="inline-message">Accepted revision {configuration.accepted_revision.revision_number} remains pinned to {configuration.accepted_revision.proposal_template.ref} v{configuration.accepted_revision.proposal_template.version} and {configuration.accepted_revision.proposal_checklist.ref} v{configuration.accepted_revision.proposal_checklist.version}.</p>}<p className="muted">{configuration?.stage1_requiredness || "Dashboard configuration is separate from Proposal source evidence."}</p></section>;
}
